// Totals values by key and answers queries.
// Usage: deno run --allow-read main.ts <file>

const MIN = -(2n ** 63n);
const MAX = 2n ** 63n - 1n;

const LF = 0x0a;
const CR = 0x0d;
const SPACE = 0x20;

// Keys are compared byte for byte, so each byte becomes one char (latin1).
// Output is converted back to the same bytes, so non-UTF-8 keys survive intact.
function bytesToKey(bytes: Uint8Array, from: number, to: number): string {
  const chars: string[] = [];
  for (let i = from; i < to; i++) chars.push(String.fromCharCode(bytes[i]));
  return chars.join("");
}

// Splits into [start, end) ranges, one per line, without the line terminator.
function splitLines(bytes: Uint8Array): [number, number][] {
  const ranges: [number, number][] = [];
  let start = 0;
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === LF) {
      ranges.push([start, trimCR(bytes, start, i)]);
      start = i + 1;
    }
  }
  if (start < bytes.length) ranges.push([start, trimCR(bytes, start, bytes.length)]);
  return ranges;
}

function trimCR(bytes: Uint8Array, start: number, end: number): number {
  return end > start && bytes[end - 1] === CR ? end - 1 : end;
}

type Total = { sum: bigint; overflow: boolean };

const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: main.ts <file>");
  Deno.exit(1);
}

const bytes = await Deno.readFile(path);
const lines = splitLines(bytes);

// The first empty line separates records from queries.
const separator = lines.findIndex(([start, end]) => start === end);
const recordCount = separator === -1 ? lines.length : separator;
const queryStart = separator === -1 ? lines.length : separator + 1;

const totals = new Map<string, Total>();

for (let n = 0; n < recordCount; n++) {
  const [start, end] = lines[n];
  // A key has no space, so the single space splits key from value.
  let space = -1;
  for (let i = end - 1; i >= start; i--) {
    if (bytes[i] === SPACE) {
      space = i;
      break;
    }
  }
  if (space === -1) continue;

  const valueText = bytesToKey(bytes, space + 1, end);
  if (!/^[+-]?\d+$/.test(valueText)) continue;
  const value = BigInt(valueText);

  const key = bytesToKey(bytes, start, space);
  let total = totals.get(key);
  if (total === undefined) {
    total = { sum: 0n, overflow: false };
    totals.set(key, total);
  }
  if (total.overflow) continue;

  total.sum += value;
  if (total.sum < MIN || total.sum > MAX) total.overflow = true;
}

const out: string[] = [];
for (let n = queryStart; n < lines.length; n++) {
  const [start, end] = lines[n];
  if (start === end) continue;

  const key = bytesToKey(bytes, start, end);
  const total = totals.get(key);
  if (total === undefined) out.push(`${key}=absent\n`);
  else if (total.overflow) out.push(`${key}=overflow\n`);
  else out.push(`${key}=${total.sum}\n`);
}

if (out.length > 0) {
  // Keys are latin1 strings, so every char maps back to one byte.
  const text = out.join("");
  const data = Uint8Array.from(text, (c) => c.charCodeAt(0));
  let offset = 0;
  while (offset < data.length) {
    offset += await Deno.stdout.write(data.subarray(offset));
  }
}

